html:
{#
  Student Fee Refund — Print Format
  App     : dux_voucher | Frappe v16 / ERPNext v16
  Module  : Dux Voucher
  Style   : Mirrors Student Fee Receipt (orange accent), adapted for
            admission-fee refunds: Fee Heads itemisation kept, accent flipped
            orange to signal outgoing money.
#}

{%- set company_doc = frappe.get_doc("Company", doc.company) %}
{%- set _raw_logo   = company_doc.get("custom_voucher_print_logo") %}
{%- if _raw_logo %}
  {%- set logo_url = frappe.utils.get_url(_raw_logo) %}
{%- else %}
  {%- set logo_url = frappe.utils.get_url("/assets/dux_voucher/images/dv_logo.png") %}
{%- endif %}
{%- set currency    = company_doc.get("default_currency") or "INR" %}
{%- set sym         = frappe.db.get_value("Currency", currency, "symbol") or "&#8377;" %}
{%- set footer_note = company_doc.get("custom_voucher_footer_note") or
    "This is a computer-generated refund voucher. Valid without physical stamp unless specified by policy." %}

{%- set _mop       = doc.get("mode_of_payment") or "" %}
{%- set _mop_type  = frappe.db.get_value("Mode of Payment", _mop, "type") if _mop else "" %}
{%- set _is_cheque = "cheque" in _mop.lower() %}
{%- set _is_bank   = (_mop_type == "Bank") and not _is_cheque %}

{%- set _ref_no_label   = "Cheque No."  if _is_cheque else ("UTR No."  if _is_bank else "Reference No.") %}
{%- set _ref_date_label = "Cheque Date" if _is_cheque else "Reference Date" %}
{%- set _show_ref = doc.get("reference_no") or doc.get("reference_date") %}

{%- set _owner_name = frappe.db.get_value("User", doc.owner, "full_name") or doc.owner %}

<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Admission Fee Refund Voucher — {{ doc.name }}</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: 'Segoe UI', Arial, sans-serif; font-size: 12px; color: #1a1a2e; background: #fff; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  .page { width: 100%; max-width: 210mm; margin: 0 auto; padding: 5mm 8mm 6mm; display: flex; flex-direction: column; gap: 0; }

  /* HEADER — green accent */
  .header { display: grid; grid-template-columns: 90px 1fr 175px; gap: 10px; align-items: flex-start; padding-bottom: 10px; border-bottom: 2.5px solid #C2410C; }
  .logo-wrap img { width: 82px; height: auto; max-height: 60px; object-fit: contain; display: block; }
  .co-name { font-size: 14px; font-weight: 700; color: #C2410C; margin-bottom: 4px; }
  .co-meta { font-size: 9.5px; color: #555; line-height: 1.65; }
  .doc-title-block { text-align: right; }
  .vch-label { font-size: 13px; font-weight: 700; color: #C2410C; letter-spacing: 1px; text-transform: uppercase; }
  .doc-no-pill { display: inline-block; margin-top: 5px; background: #FFEDD5; color: #4A1D03; font-size: 11px; font-weight: 700; padding: 3px 10px; border-radius: 4px; }
  .date-label { font-size: 8.5px; color: #888; text-transform: uppercase; letter-spacing: 0.5px; margin-top: 7px; }
  .date-value { font-size: 12px; font-weight: 600; color: #1a1a2e; margin-top: 2px; }

  /* META STRIP */
  .meta-strip { display: grid; grid-template-columns: 1fr 1fr 1fr; border: 0.5px solid #fbd9b4; border-top: none; }
  .mc { padding: 7px 11px; border-right: 0.5px solid #fbd9b4; }
  .mc:last-child { border-right: none; }
  .mc-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.6px; color: #888; margin-bottom: 3px; }
  .mc-value { font-size: 11px; font-weight: 600; color: #1a1a2e; }

  /* SECTION TITLE */
  .sec-title { background: #fff7ed; border-top: 0.5px solid #fbd9b4; border-bottom: 0.5px solid #fbd9b4; padding: 5px 11px; font-size: 8.5px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.7px; color: #C2410C; margin-top: 6px; }

  /* STUDENT INFO TABLE (key-value pairs) */
  table.kv { width: 100%; border-collapse: collapse; border: 0.5px solid #fbd9b4; border-top: none; }
  table.kv td { padding: 7px 11px; border-bottom: 0.5px solid #fde9d2; vertical-align: middle; font-size: 11px; color: #1a1a2e; }
  table.kv tr:last-child td { border-bottom: none; }
  table.kv td.k { width: 170px; font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; font-weight: 700; border-right: 0.5px solid #fde9d2; background: #fffaf5; }
  table.kv td.v { font-size: 12px; font-weight: 600; color: #1a1a2e; }
  table.kv td.v-big { font-size: 14px; font-weight: 700; color: #C2410C; }

  /* REFERENCE STRIP */
  .ref-row { display: grid; grid-template-columns: 1fr 1fr; border: 0.5px solid #fbd9b4; border-top: none; }
  .ref-cell { padding: 6px 11px; border-right: 0.5px solid #fbd9b4; }
  .ref-cell:last-child { border-right: none; }
  .ref-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; margin-bottom: 2px; }
  .ref-value { font-size: 11px; font-weight: 600; color: #1a1a2e; }

  /* FEE HEADS TABLE — itemised breakdown */
  table.heads { width: 100%; border-collapse: collapse; border: 0.5px solid #fbd9b4; border-top: none; }
  table.heads thead th { background: #fffaf5; padding: 7px 11px; font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; font-weight: 700; border-bottom: 0.5px solid #fbd9b4; }
  table.heads thead th.r { text-align: right; }
  table.heads td { padding: 8px 11px; border-bottom: 0.5px solid #fde9d2; font-size: 11px; }
  table.heads tr:last-child td { border-bottom: none; }
  table.heads td.k { color: #1a1a2e; font-weight: 600; }
  table.heads td.r { text-align: right; font-variant-numeric: tabular-nums; font-family: 'Courier New', monospace; font-size: 11.5px; white-space: nowrap; color: #1a1a2e; }
  table.heads tr.total td { background: #fff7ed; font-weight: 700; color: #C2410C; border-top: 1.5px solid #C2410C; padding: 9px 11px; }
  table.heads tr.total td.r { font-size: 13px; }

  /* TOTALS BAR (amount-in-words + big amount) */
  .totals-bar { display: flex; justify-content: space-between; align-items: center; padding: 9px 11px; border: 0.5px solid #fbd9b4; border-top: 1.5px solid #C2410C; background: #fff7ed; margin-top: 6px; }
  .w-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; margin-bottom: 3px; }
  .w-value { font-size: 10.5px; font-style: italic; color: #C2410C; font-weight: 600; max-width: 340px; }
  .a-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; margin-bottom: 2px; text-align: right; }
  .a-value { font-size: 22px; font-weight: 700; color: #C2410C; text-align: right; }

  /* REMARKS */
  .remarks-block { border: 0.5px solid #fbd9b4; border-top: none; padding: 7px 11px; }
  .r-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; margin-bottom: 3px; }
  .r-value { font-size: 11px; color: #333; line-height: 1.5; }

  /* SIGNATURES */
  .sig-strip { display: grid; grid-template-columns: 1fr 1fr 1fr; border: 0.5px solid #fbd9b4; margin-top: 14px; }
  .sig-cell { padding: 7px 14px 9px; border-right: 0.5px solid #fbd9b4; text-align: center; }
  .sig-cell:last-child { border-right: none; }
  .sig-space { height: 34px; }
  .sig-line { border-top: 1px solid #C2410C; margin-bottom: 4px; }
  .sig-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.6px; color: #555; }
  .sig-name  { font-size: 9px; color: #C2410C; font-weight: 600; margin-top: 2px; }

  /* PAGE FOOTER */
  .page-footer { margin-top: 10px; padding-top: 8px; border-top: 0.5px solid #fbd9b4; display: flex; justify-content: space-between; align-items: center; }
  .page-footer .note { font-size: 8.5px; color: #aaa; font-style: italic; max-width: 480px; }
  .page-footer .brand { font-size: 8.5px; color: #aaa; white-space: nowrap; }
  .page-footer .brand strong { color: #C2410C; }

  @media print {
    body { background: white; }
    .page { padding: 3mm 5mm; margin: 0; width: 100%; max-width: 100%; }
    @page { size: A4; margin: 10mm; }
  }
</style>
</head>
<body>
<div class="page">

  {# ══ HEADER ══════════════════════════════════════════════════════ #}
  <div class="header">
    <div class="logo-wrap">
      <img src="{{ logo_url }}" alt="{{ company_doc.company_name or doc.company }}">
    </div>
    <div>
      <div class="co-name">{{ company_doc.company_name or doc.company }}</div>
      <div class="co-meta">
        {%- if company_doc.get("gstin") %}GSTIN: {{ company_doc.gstin }}{%- if company_doc.get("tax_id") %} &nbsp;|&nbsp; PAN: {{ company_doc.tax_id }}{%- endif %}<br>{%- elif company_doc.get("tax_id") %}PAN: {{ company_doc.tax_id }}<br>{%- endif %}
        {%- set addr_id = frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": company_doc.name, "parenttype": "Address"}, "parent") %}
        {%- if addr_id %}
          {%- set a = frappe.get_doc("Address", addr_id) %}
          {%- set addr_parts = [a.address_line1, a.address_line2, a.city, a.state, a.pincode] | select | join(", ") %}
          {{ addr_parts }}<br>
        {%- endif %}
        {%- if company_doc.get("phone_no") %}Ph: {{ company_doc.phone_no }}{%- endif %}{%- if company_doc.get("phone_no") and company_doc.get("email") %} &nbsp;|&nbsp; {%- endif %}{%- if company_doc.get("email") %}{{ company_doc.email }}{%- endif %}
      </div>
    </div>
    <div class="doc-title-block">
      <div class="vch-label">Admission Fee Refund Voucher</div>
      <div><span class="doc-no-pill">{{ doc.name }}</span></div>
      <div class="date-label">Date</div>
      <div class="date-value">{{ frappe.format(doc.posting_date, {"fieldtype": "Date"}) }}</div>
    </div>
  </div>

  {# ══ META STRIP ═════════════════════════════════════════════════ #}
  <div class="meta-strip">
    <div class="mc">
      <div class="mc-label">Payment Method</div>
      <div class="mc-value">{{ _mop or "&#8212;" }}</div>
    </div>
    <div class="mc">
      <div class="mc-label">Paid From Account</div>
      <div class="mc-value">{{ doc.get("paid_from_account") or "&#8212;" }}</div>
    </div>
    <div class="mc">
      <div class="mc-label">Ledger Head</div>
      <div class="mc-value">Admission/Registration Fee (Provisional)</div>
    </div>
  </div>

  {# ══ STUDENT DETAILS ════════════════════════════════════════════ #}
  <div class="sec-title">Paid to</div>
  <table class="kv">
    <tr>
      <td class="k">Student Name</td>
      <td class="v v-big">{{ doc.student_name or doc.student }}</td>
    </tr>
    <tr>
      <td class="k">Father's Name</td>
      <td class="v">{{ doc.father_name or "&#8212;" }}</td>
    </tr>
    <tr>
      <td class="k">Course</td>
      <td class="v">{{ doc.course or "&#8212;" }}</td>
    </tr>
    <tr>
      <td class="k">Admission Year</td>
      <td class="v">{{ doc.admission_year or "&#8212;" }}</td>
    </tr>
    <tr>
      <td class="k">Student ID</td>
      <td class="v">{{ doc.student }}</td>
    </tr>
  </table>

  {# ══ REFERENCE STRIP ════════════════════════════════════════════ #}
  {%- if _show_ref %}
  <div class="sec-title">Payment Reference</div>
  <div class="ref-row">
    <div class="ref-cell">
      <div class="ref-label">{{ _ref_no_label }}</div>
      <div class="ref-value">{{ doc.get("reference_no") or "&#8212;" }}</div>
    </div>
    <div class="ref-cell">
      <div class="ref-label">{{ _ref_date_label }}</div>
      <div class="ref-value">
        {%- if doc.get("reference_date") %}{{ frappe.format(doc.reference_date, {"fieldtype": "Date"}) }}{%- else %}&#8212;{%- endif %}
      </div>
    </div>
  </div>
  {%- endif %}

  {# ══ FEE HEADS BREAKDOWN ════════════════════════════════════════ #}
  <div class="sec-title">Fee Heads</div>
  <table class="heads">
    <thead>
      <tr>
        <th>Head</th>
        <th class="r">Amount</th>
      </tr>
    </thead>
    <tbody>
      {%- for row in doc.heads %}
      {%- set head_doc = frappe.get_cached_doc("Course Fee Head", row.head) %}
      <tr>
        <td class="k">{{ head_doc.head_name }}</td>
        <td class="r">{{ frappe.utils.fmt_money(row.amount, currency=currency) }}</td>
      </tr>
      {%- endfor %}
      <tr class="total">
        <td class="k">Total</td>
        <td class="r">{{ frappe.utils.fmt_money(doc.total_amount, currency=currency) }}</td>
      </tr>
    </tbody>
  </table>

  {# ══ TOTALS BAR (amount in words) ═══════════════════════════════ #}
  <div class="totals-bar">
    <div>
      <div class="w-label">Amount in words</div>
      <div class="w-value">
        {%- set _words = frappe.utils.money_in_words(doc.total_amount, main_currency=currency) or "&#8212;" %}
        {{ _words.replace("INR ", "").replace("USD ", "").replace("EUR ", "") if _words != "&#8212;" else "&#8212;" }}
      </div>
    </div>
    <div>
      <div class="a-label">Amount Refunded</div>
      <div class="a-value">{{ frappe.utils.fmt_money(doc.total_amount, currency=currency) }}</div>
    </div>
  </div>

  {# ══ REMARKS ════════════════════════════════════════════════════ #}
  {%- if doc.get("remarks") %}
  <div class="remarks-block">
    <div class="r-label">Remarks / Narration</div>
    <div class="r-value">{{ doc.remarks }}</div>
  </div>
  {%- endif %}

  {# ══ SIGNATURES ═════════════════════════════════════════════════ #}
  <div class="sig-strip">
    <div class="sig-cell">
      <div class="sig-space"></div>
      <div class="sig-line"></div>
      <div class="sig-label">Prepared By</div>
      <div class="sig-name">{{ _owner_name }}</div>
    </div>
    <div class="sig-cell">
      <div class="sig-space"></div>
      <div class="sig-line"></div>
      <div class="sig-label">Verified By</div>
    </div>
    <div class="sig-cell">
      <div class="sig-space"></div>
      <div class="sig-line"></div>
      <div class="sig-label">Authorised Signatory</div>
    </div>
  </div>

  {# ══ PAGE FOOTER ════════════════════════════════════════════════ #}
  <div class="page-footer">
    <div class="note">{{ footer_note }}</div>
    <div class="brand">Powered by <strong>DUX DigiTech</strong></div>
  </div>

</div>
</body>
</html>
